/**
 * Unit tests for CommandLineRunner.createOptions.
 * Since createOptions is protected, we use a Test subclass to expose it.
 */
public class CommandLineRunner_createOptions_TriageGen1Test {

    // Test subclass to access the protected method
    private static class TestableCommandLineRunner extends CommandLineRunner {
        public TestableCommandLineRunner(String[] args) {
            super(args);
        }

        @Override
        public CompilerOptions createOptions() {
            return super.createOptions();
        }
    }

    // Mock class for flags access since flags is likely an internal field of CommandLineRunner
    // In real Closure Compiler, flags is a field of type CommandLineRunner.Flags
    // For the purpose of this test, we assume flags is accessible via the constructor or reflection 
    // if it's not public. However, based on the snippet, we must manipulate the 'flags' object.

    @Test
    public void testCreateOptions_FullCoverage() {
        // Setup flags
        CommandLineRunner.Flags flags = new CommandLineRunner.Flags();

        // 1. Test basic path (debug=false, generate_exports=false)
        flags.compilation_level = mock(CompilationLevel.class);
        flags.debug = false;
        flags.generate_exports = false;
        flags.warning_level = mock(WarningLevel.class);
        flags.formatting = Collections.emptyList();
        flags.process_closure_primitives = false;

        TestableCommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
        // Manually inject flags if possible, or assume constructor sets it.
        // Given the prompt, we assume we can set the state of 'flags' inside the runner.
        setFlags(runner, flags);

        CompilerOptions options = runner.createOptions();

        assertThat(options.getCodingConvention()).isInstanceOf(com.google.javascript.jscomp.ClosureCodingConvention.class);
        verify(flags.compilation_level).setOptionsForCompilationLevel(options);
        verify(flags.warning_level).setOptionsForWarningLevel(options);
        assertThat(options.closurePass).isFalse();
    }

    @Test
    public void testCreateOptions_WithDebugAndExports() {
        // 2. Test path (debug=true, generate_exports=true)
        CommandLineRunner.Flags flags = new CommandLineRunner.Flags();
        flags.compilation_level = mock(CompilationLevel.class);
        flags.debug = true;
        flags.generate_exports = true;
        flags.warning_level = mock(WarningLevel.class);
        flags.formatting = Collections.emptyList();
        flags.process_closure_primitives = true;

        TestableCommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
        setFlags(runner, flags);

        CompilerOptions options = runner.createOptions();

        verify(flags.compilation_level).setDebugOptionsForCompilationLevel(options);
        assertThat(options.isGenerateExports()).isTrue();
        assertThat(options.closurePass).isTrue();
    }

    @Test
    public void testCreateOptions_WithFormattingOptions() {
        // 3. Test path (formatting list not empty)
        CommandLineRunner.Flags flags = new CommandLineRunner.Flags();
        flags.compilation_level = mock(CompilationLevel.class);
        flags.debug = false;
        flags.generate_exports = false;
        flags.warning_level = mock(WarningLevel.class);

        FormattingOption mockFormat = mock(FormattingOption.class);
        flags.formatting = Arrays.asList(mockFormat);
        flags.process_closure_primitives = false;

        TestableCommandLineRunner runner = new TestableCommandLineRunner(new String[]{});
        setFlags(runner, flags);

        CompilerOptions options = runner.createOptions();

        verify(mockFormat).applyToOptions(options);
    }

    /**
     * Helper to inject flags into the protected field 'flags' using reflection
     * because CommandLineRunner.flags is typically private/protected.
     */
    private void setFlags(TestableCommandLineRunner runner, CommandLineRunner.Flags flags) {
        try {
            java.lang.reflect.Field field = CommandLineRunner.class.getDeclaredField("flags");
            field.setAccessible(true);
            field.set(runner, flags);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
